def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the full row or column that forms the 2-colored divider.
    lines = []
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            lines.append(("h", r))
    for c in range(w):
        if all(grid[r][c] == 2 for r in range(h)):
            lines.append(("v", c))
    if not lines:
        return out
    orient, axis = max(lines, key=lambda x: h if x[0] == "h" else w)

    # The most common non-divider color is the background.
    counts = {}
    for row in grid:
        for value in row:
            if value != 2:
                counts[value] = counts.get(value, 0) + 1
    if not counts:
        return out
    background = max(counts, key=counts.get)

    # Locate the non-background object.
    positions = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] not in (2, background)]
    if not positions:
        return out
    color_counts = {}
    for r, c in positions:
        color_counts[grid[r][c]] = color_counts.get(grid[r][c], 0) + 1
    obj_color = max(color_counts, key=color_counts.get)
    obj = [(r, c) for r, c in positions if grid[r][c] == obj_color]

    if orient == "v":
        left = [c for r, c in obj if c < axis]
        right = [c for r, c in obj if c > axis]
        if left and right:
            return out
        if right:
            delta = axis + 1 - min(right)
            far = max(right) + delta
            stripe = far + 1
            dr, dc = 0, delta
            stripe_is_row = False
        elif left:
            delta = axis - 1 - max(left)
            far = min(left) + delta
            stripe = far - 1
            dr, dc = 0, delta
            stripe_is_row = False
        else:
            return out
        if not (0 <= stripe < w):
            return out
    else:
        above = [r for r, c in obj if r < axis]
        below = [r for r, c in obj if r > axis]
        if above and below:
            return out
        if below:
            delta = axis + 1 - min(below)
            far = max(below) + delta
            stripe = far + 1
            dr, dc = delta, 0
            stripe_is_row = True
        elif above:
            delta = axis - 1 - max(above)
            far = min(above) + delta
            stripe = far - 1
            dr, dc = delta, 0
            stripe_is_row = True
        else:
            return out
        if not (0 <= stripe < h):
            return out

    # Move the object toward the divider, leaving background in its old place.
    for r, c in obj:
        out[r][c] = background
    for r, c in obj:
        out[r + dr][c + dc] = obj_color

    # Mark the object's far edge with a full stripe.
    if stripe_is_row:
        for c in range(w):
            out[stripe][c] = 8
    else:
        for r in range(h):
            out[r][stripe] = 8

    return out
